//! The frozen baseline corpus (ADR-4233 decision 9, "Frozen corpus").
//!
//! The baseline writes a fixture corpus with its own real write paths under
//! `crates/ravel-compat-tests/corpus/<release>/`, with the exact expected
//! results recorded beside it in `expected.txt`. Corpora are append-only (the
//! `check-compat-corpus-append-only.sh` guard enforces it); every later release
//! opens the corpus and asserts exact results. These fixtures are written by a
//! released build's code, not regenerated by the release under test.
//!
//! On-disk shape: every object is one file `objects/<NNNN>.bin` and
//! `manifest.txt` maps each index to the object's real store key. The read test
//! loads them into a `MemoryStore` under their real keys and reads with the
//! current build. (A disk `ScratchStore` is not used: it clears its directory
//! on open, which would wipe the frozen fixtures.)
//!
//! Two entry points:
//!   - `reads_the_frozen_v0_34_0_corpus` (the real test) loads the committed
//!     corpus and asserts every recorded fact exactly;
//!   - `generate_corpus` (`#[ignore]`, run by hand to FREEZE a new corpus)
//!     writes the fixtures and `expected.txt`.
//!
//! Scope: this baseline corpus covers metrics (RSEG), written by the real
//! segment codec the ingest flush uses, plus a real compaction (L0 -> L1) by
//! `compact_bucket`. The logs/spans signals and the ingest-router-driven and
//! fold-driven corpora are a later append under the same append-only directory
//! (the guard allows additions); see the task report.

#![allow(clippy::expect_used, clippy::unwrap_used)]

use std::collections::BTreeMap;
use std::path::PathBuf;

use ravel_catalog::{AbsentPolicy, validate_or_adopt};
use ravel_commit::keys;
use ravel_commit::record::{self, NewCommitRecord};
use ravel_maintain::{
    Bucket, CompactionOutcome, CompactorConfig, FixedClock, compact_bucket, read,
};
use ravel_object_store::memory::MemoryStore;
use ravel_object_store::{GetRange, ObjectStoreBackend, PutOptions, list_all};
use ravel_segment::{
    IngestBounds, ReaderLimits, SegmentIdentity, SegmentWriter, SeriesInput, VERSION_V7,
    open_from_full,
};
use ravel_types::{Label, LabelSet, Sample, SeriesId, Signal, TenantHash, TenantId};
use uuid::Uuid;

const RELEASE: &str = "v0.34.0";
const NS_PER_HOUR: i64 = 3_600_000_000_000;
const HOUR: u32 = 495_000;
const SHARD: u32 = 0;

fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("corpus")
        .join(RELEASE)
}

fn objects_dir() -> PathBuf {
    corpus_dir().join("objects")
}

fn manifest_path() -> PathBuf {
    corpus_dir().join("manifest.txt")
}

fn expected_path() -> PathBuf {
    corpus_dir().join("expected.txt")
}

fn tenant() -> TenantId {
    TenantId::new("acme")
}

fn hash() -> TenantHash {
    tenant().hash()
}

fn bucket() -> Bucket {
    Bucket::new(hash(), Signal::Metrics, SHARD, HOUR)
}

/// A time well past the seal margin for [`HOUR`], so the bucket is sealed.
fn sealed_now_ns() -> i64 {
    (i64::from(HOUR) + 1) * NS_PER_HOUR + 3 * NS_PER_HOUR
}

fn series(name: &str, value: f64, ts_ns: i64) -> SeriesInput {
    let labels = LabelSet::new(vec![Label {
        name: "__name__".to_string(),
        value: name.to_string(),
    }])
    .expect("labels");
    SeriesInput {
        series_id: SeriesId::compute(&tenant(), name, &labels).expect("series id"),
        labels,
        samples: vec![Sample { ts_ns, value }],
    }
}

/// Write one real RSEG v7 L0 object and its commit record at `seq`.
async fn write_l0(store: &dyn ObjectStoreBackend, seq: u64, inputs: Vec<SeriesInput>) {
    let writer_id = Uuid::from_u128(0xC0_0000 + u128::from(seq));
    let epoch = 1u64;
    let event_ns = i64::from(HOUR) * NS_PER_HOUR + (seq as i64) * 1_000_000;
    let written = SegmentWriter::write(
        inputs,
        SegmentIdentity {
            tenant_hash: hash().0,
            shard: SHARD,
            writer_id: writer_id.to_string(),
            writer_epoch: epoch,
            writer_seq: seq,
        },
        IngestBounds {
            min_ingest_ts_ns: event_ns,
            max_ingest_ts_ns: event_ns,
        },
    )
    .expect("write RSEG v7");
    let data_key = keys::data_key(
        &hash(),
        Signal::Metrics,
        SHARD,
        writer_id,
        epoch,
        seq,
        &written.summary.blake3,
    )
    .expect("data key");
    let commit = record::build(NewCommitRecord {
        tenant_hash: hash(),
        signal: Signal::Metrics,
        shard: SHARD,
        writer_id,
        writer_epoch: epoch,
        writer_seq: seq,
        object_size: written.bytes.len() as u64,
        content_hash: written.summary.blake3,
        sample_count: written.summary.sample_count,
        series_count: written.summary.series_count,
        min_event_ts_ns: written.summary.min_event_ts_ns,
        max_event_ts_ns: written.summary.max_event_ts_ns,
        min_ingest_ts_ns: event_ns,
        max_ingest_ts_ns: event_ns,
        segment_format_version: u32::from(VERSION_V7),
        created_unix_ns: event_ns,
        ingest_hour_bucket: u32::try_from(event_ns.div_euclid(NS_PER_HOUR)).expect("hour"),
    })
    .expect("build commit record");
    store
        .put(&data_key, written.bytes.clone(), PutOptions::default())
        .await
        .expect("put data object");
    store
        .put(
            &keys::commit_key_for_record(&commit).expect("commit key"),
            record::encode(&commit),
            PutOptions::default(),
        )
        .await
        .expect("put commit record");
}

/// Facts a reader recomputes from the frozen corpus and checks against the
/// recorded `expected.txt`.
#[derive(Debug, PartialEq, Eq)]
struct Facts {
    rseg_data_objects: u64,
    l0_commit_records: u64,
    l0_sample_count: u64,
    l0_series_count: u64,
    compaction_records: u64,
    l1_sample_count: u64,
    l1_series_count: u64,
}

/// Read every object with the current build and compute the exact facts: every
/// RSEG data object opens at version 7, the L0 commit records sum to the
/// recorded counts, and the compaction record's parts carry the conserved
/// sample count at version 7.
async fn compute_facts(store: &dyn ObjectStoreBackend) -> Facts {
    let mut rseg_data_objects = 0;
    for meta in list_all(store, "").await.expect("list") {
        if meta.key.ends_with(".rseg") {
            let bytes = store
                .get(&meta.key, GetRange::Full)
                .await
                .expect("get")
                .data;
            let loc = open_from_full(&bytes, ReaderLimits::default()).expect("open rseg");
            assert_eq!(loc.version, VERSION_V7, "{}", meta.key);
            rseg_data_objects += 1;
        }
    }

    let listing = read::list_bucket(store, &bucket())
        .await
        .expect("list bucket");
    let (mut l0_sample_count, mut l0_series_count) = (0u64, 0u64);
    for key in &listing.commit_keys {
        let bytes = store.get(key, GetRange::Full).await.expect("get").data;
        let rec = record::decode(&bytes).expect("decode commit");
        assert_eq!(rec.segment_format_version, u32::from(VERSION_V7), "{key}");
        l0_sample_count += rec.sample_count;
        l0_series_count += rec.series_count;
    }
    let (mut l1_sample_count, mut l1_series_count) = (0u64, 0u64);
    for key in &listing.compaction_record_keys {
        let bytes = store.get(key, GetRange::Full).await.expect("get").data;
        let rec = record::decode_compaction(&bytes).expect("decode compaction");
        for part in &rec.parts {
            assert_eq!(part.segment_format_version, u32::from(VERSION_V7), "{key}");
            l1_sample_count += part.sample_count;
            l1_series_count += part.series_count;
        }
    }
    Facts {
        rseg_data_objects,
        l0_commit_records: listing.commit_keys.len() as u64,
        l0_sample_count,
        l0_series_count,
        compaction_records: listing.compaction_record_keys.len() as u64,
        l1_sample_count,
        l1_series_count,
    }
}

fn facts_to_lines(f: &Facts) -> String {
    format!(
        "rseg_data_objects={}\nl0_commit_records={}\nl0_sample_count={}\nl0_series_count={}\n\
         compaction_records={}\nl1_sample_count={}\nl1_series_count={}\n",
        f.rseg_data_objects,
        f.l0_commit_records,
        f.l0_sample_count,
        f.l0_series_count,
        f.compaction_records,
        f.l1_sample_count,
        f.l1_series_count,
    )
}

fn facts_from_lines(text: &str) -> Facts {
    let map: BTreeMap<&str, u64> = text
        .lines()
        .filter_map(|l| l.split_once('='))
        .map(|(k, v)| (k.trim(), v.trim().parse().expect("number")))
        .collect();
    let get = |k: &str| *map.get(k).unwrap_or_else(|| panic!("missing {k}"));
    Facts {
        rseg_data_objects: get("rseg_data_objects"),
        l0_commit_records: get("l0_commit_records"),
        l0_sample_count: get("l0_sample_count"),
        l0_series_count: get("l0_series_count"),
        compaction_records: get("compaction_records"),
        l1_sample_count: get("l1_sample_count"),
        l1_series_count: get("l1_series_count"),
    }
}

/// Load the frozen objects into a `MemoryStore` under their real keys.
async fn load_corpus() -> MemoryStore {
    let store = MemoryStore::with_page_size(2);
    let manifest = std::fs::read_to_string(manifest_path()).expect("read manifest");
    for line in manifest.lines() {
        let (index, key) = line.split_once('\t').expect("manifest line");
        let bytes = std::fs::read(objects_dir().join(format!("{index}.bin"))).expect("read object");
        store
            .put(key, bytes.into(), PutOptions::default())
            .await
            .expect("load object");
    }
    store
}

/// The real test: load the committed corpus and assert the recorded facts hold
/// exactly against the current build.
#[tokio::test]
async fn reads_the_frozen_v0_34_0_corpus() {
    assert!(
        manifest_path().exists(),
        "the frozen corpus is committed under {}; run `cargo test --test corpus -- --ignored \
         generate_corpus` to create it",
        corpus_dir().display()
    );
    let store = load_corpus().await;

    let facts = compute_facts(&store).await;
    let expected =
        facts_from_lines(&std::fs::read_to_string(expected_path()).expect("read expected"));
    assert_eq!(
        facts, expected,
        "the current build reads the corpus exactly"
    );

    // Conservation: compaction preserves the sample count.
    assert_eq!(
        facts.l1_sample_count, facts.l0_sample_count,
        "compaction conserves samples"
    );
}

/// Run by hand to FREEZE a corpus (`#[ignore]`): writes the object fixtures,
/// the manifest and `expected.txt`, then verifies the frozen corpus reads back.
#[tokio::test]
#[ignore = "writes the frozen corpus fixtures; run by hand to (re)create a release corpus"]
async fn generate_corpus() {
    let store = MemoryStore::with_page_size(2);
    validate_or_adopt(
        &store,
        &hash(),
        Signal::Metrics,
        SHARD + 1,
        i64::from(HOUR) * NS_PER_HOUR,
        AbsentPolicy::CreateFromConfig,
    )
    .await
    .expect("provision");

    // Two L0 inputs in the same sealed hour: input 1 writes series a and b,
    // input 2 writes another sample of a. Compaction merges them into one L1.
    write_l0(
        &store,
        1,
        vec![
            series("corpus_a", 1.0, i64::from(HOUR) * NS_PER_HOUR + 1000),
            series("corpus_b", 2.0, i64::from(HOUR) * NS_PER_HOUR + 1000),
        ],
    )
    .await;
    write_l0(
        &store,
        2,
        vec![series(
            "corpus_a",
            3.0,
            i64::from(HOUR) * NS_PER_HOUR + 2000,
        )],
    )
    .await;

    let outcome = compact_bucket(
        &store,
        &FixedClock::new(sealed_now_ns()),
        &CompactorConfig::default(),
        &bucket(),
    )
    .await
    .expect("compact");
    assert!(
        matches!(outcome, CompactionOutcome::Compacted { .. }),
        "{outcome:?}"
    );

    // Dump every object (sorted by key, so the fixture is deterministic) to its
    // own file, with a manifest mapping index -> real key.
    std::fs::create_dir_all(objects_dir()).expect("create objects dir");
    let mut manifest = String::new();
    for (index, meta) in list_all(&store, "")
        .await
        .expect("list")
        .into_iter()
        .enumerate()
    {
        let bytes = store
            .get(&meta.key, GetRange::Full)
            .await
            .expect("get")
            .data;
        std::fs::write(objects_dir().join(format!("{index:04}.bin")), &bytes)
            .expect("write object");
        manifest.push_str(&format!("{index:04}\t{}\n", meta.key));
    }
    std::fs::write(manifest_path(), manifest).expect("write manifest");

    let facts = compute_facts(&store).await;
    std::fs::write(expected_path(), facts_to_lines(&facts)).expect("write expected.txt");

    // Prove the frozen fixtures read back exactly through the load path.
    let reloaded = load_corpus().await;
    assert_eq!(compute_facts(&reloaded).await, facts);
}
